-- composition of rule kernels L:eliminate_join x P:FilterPushdown (datafusion), template graft_scalar
WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT a2.c1 AS c0, a1.c1 AS c1 FROM ((SELECT * FROM ti WHERE (SELECT count(*) FROM (SELECT DISTINCT '0 days'::interval AS c0, make_array('a', 'b') AS c1, '1970-01-01'::date AS c2 FROM (t4 AS a1 JOIN t4 AS a2 ON (a1.c3 = a2.c3)) WHERE COALESCE ((LENGTH ((SELECT STRING_AGG ('NaN'::text, ',' ORDER BY 'NaN'::text) FROM tp AS a3)) <> a2.c0), (a1.c0 IS DISTINCT FROM a2.c0))) AS kb) >= 0) AS a1 JOIN (t2 AS a2 JOIN v0 AS a3 ON (a2.c0 = a3.n)) ON ((a1.c0 = a3.c0) AND FALSE));
-- pgfuzz:check kernel:graft_scalar WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT a2.c1 AS c0, a1.c1 AS c1 FROM (ti AS a1 JOIN (t2 AS a2 JOIN v0 AS a3 ON (a2.c0 = a3.n)) ON ((a1.c0 = a3.c0) AND FALSE))
